head.script:
// 

    tailwind.config = {
      darkMode: "class",
      theme: {
        extend: {
          colors: {
            primary: {
              800: '#1e3a5f',
              900: '#163355',
              950: '#0b1a30',
            },
            gold: {
              400: '#fbbf24',
              500: '#d4af37',
              600: '#c59b27',
              700: '#a17a1a',
            }
          },
          fontFamily: {
            cairo: ['Cairo', 'sans-serif'],
            amiri: ['Amiri', 'serif'],
          }
        }
      }
    }

//

body.script:
// 

    let currentPkg = { id: 'pkg-shaban-ramadan', title: 'عمرة شعبان ورمضان المباركة 1446', basePrice: 18500 };
    let discount = 0;
    let lastBooking = null;

    function openBookingModal(id, title, basePrice) {
      currentPkg = { id, title, basePrice };
      document.getElementById('modalPkgTitle').innerText = title;
      discount = 0;
      document.getElementById('modalCoupon').value = '';
      document.getElementById('couponNotice').classList.add('hidden');
      calculateModalPrice();
      const modal = document.getElementById('bookingModal');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function closeBookingModal() {
      const modal = document.getElementById('bookingModal');
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }

    function calculateModalPrice() {
      const travelers = parseInt(document.getElementById('modalTravelers').value) || 2;
      const roomType = document.getElementById('modalRoomType').value;
      let roomAddon = 0;
      if (roomType === 'triple') roomAddon = 1000;
      if (roomType === 'double') roomAddon = 2000;
      if (roomType === 'quint') roomAddon = -500;

      const pricePerPerson = Math.max(10000, currentPkg.basePrice + roomAddon);
      const subtotal = pricePerPerson * travelers;
      const grandTotal = Math.max(0, subtotal - discount);

      const payPlan = document.querySelector('input[name="payPlan"]:checked').value;
      const payableNow = payPlan === 'deposit' ? Math.round(grandTotal * 0.3) : grandTotal;

      document.getElementById('modalGrandTotal').innerText = grandTotal.toLocaleString('ar-MA') + ' د.م';
      document.getElementById('modalPayableNow').innerText = payableNow.toLocaleString('ar-MA') + ' د.م';
    }

    function applyCoupon() {
      const code = document.getElementById('modalCoupon').value.trim().toUpperCase();
      const notice = document.getElementById('couponNotice');
      if (code === 'RAMADANMUBARAK') {
        discount = 1000;
        notice.innerText = '✓ تم تطبيق خصم بقيمة 1,000 درهم على الإجمالي!';
        notice.className = 'text-xs font-bold text-gold-500 block';
      } else {
        discount = 0;
        notice.innerText = 'كود الخصم غير صحيح أو منتهي الصلاحية';
        notice.className = 'text-xs font-bold text-rose-600 block';
      }
      calculateModalPrice();
    }

    function handleBookingSubmit(e) {
      e.preventDefault();
      const name = document.getElementById('modalFullName').value.trim();
      const phone = document.getElementById('modalPhone').value.trim();
      const travelers = document.getElementById('modalTravelers').value;
      const grandTotal = document.getElementById('modalGrandTotal').innerText;
      const payableNow = document.getElementById('modalPayableNow').innerText;

      const randomSuffix = Math.floor(1000 + Math.random() * 9000);
      const code = `RAK-2026-${randomSuffix}`;

      lastBooking = {
        code,
        name,
        phone,
        pkg: currentPkg.title,
        travelers,
        grandTotal,
        payableNow
      };

      // Add to admin list
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="p-2.5 font-mono font-bold" dir="ltr">${code}</td>
        <td class="p-2.5 font-bold">${name} (${travelers})</td>
        <td class="p-2.5">${currentPkg.title}</td>
        <td class="p-2.5 font-bold text-gold-500">${grandTotal}</td>
        <td class="p-2.5"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">طلب جديد</span></td>
      `;
      document.getElementById('adminBookingsTable').prepend(tr);

      // Close booking modal and show voucher
      closeBookingModal();
      document.getElementById('voucherCode').innerText = code;
      document.getElementById('voucherName').innerText = name;
      document.getElementById('voucherPkg').innerText = currentPkg.title;
      document.getElementById('voucherTotal').innerText = grandTotal;
      document.getElementById('voucherPayable').innerText = payableNow;

      const vModal = document.getElementById('voucherModal');
      vModal.classList.remove('hidden');
      vModal.classList.add('flex');
    }

    function notifyWhatsAppVoucher() {
      if (!lastBooking) return;
      const text = encodeURIComponent(`السلام عليكم، قمت بحجز رحلة عبر الموقع:\nرقم الحجز: ${lastBooking.code}\nالاسم: ${lastBooking.name}\nالبرنامج: ${lastBooking.pkg}\nالمبلغ: ${lastBooking.grandTotal}`);
      window.open(`https://wa.me/212662574740?text=${text}`, '_blank');
    }

    function openTrackerModal() {
      const modal = document.getElementById('trackerModal');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function trackBooking() {
      const input = document.getElementById('trackCodeInput').value.trim().toUpperCase();
      const result = document.getElementById('trackResult');
      if (!input) return;

      result.classList.remove('hidden');
      if (input.includes('9041')) {
        result.innerHTML = `
          <div class="text-gold-500 font-bold">✓ الحجز مؤكد: RAK-2026-9041</div>
          <div>المسافر: الحاج رشيد التازي</div>
          <div>البرنامج: عمرة شعبان ورمضان المباركة 1446</div>
          <div>تاريخ السفر: 2026-02-18 (الدار البيضاء)</div>
          <div>الدفعة المسددة: 12,300 د.م (عربون 30%)</div>
          <div>المتبقي: 28,700 د.م</div>
        `;
      } else if (input.includes('8812')) {
        result.innerHTML = `
          <div class="text-gold-500 font-bold">✓ الحجز مدفوع بالكامل: RAK-2026-8812</div>
          <div>المسافر: عمر العلمي (4 مسافرين)</div>
          <div>البرنامج: عمرة عبر تركيا - إسطنبول ومكة والمدينة</div>
          <div>المسدد: 67,000 د.م (مدفوع بالكامل)</div>
        `;
      } else {
        result.innerHTML = `
          <div class="text-amber-800 font-bold">الحجز ${input} مسجل وقيد المراجعة</div>
          <div>جاري مطابقة إيصال الدفع وتأكيد تصريح الروضة وتذاكر الطيران.</div>
        `;
      }
    }

    function openAdminModal() {
      const modal = document.getElementById('adminModal');
      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function filterPackages() {
      const cat = document.getElementById('searchCategory').value;
      const cards = document.querySelectorAll('.pkg-card');
      cards.forEach(card => {
        if (cat === 'all' || card.dataset.category === cat) {
          card.classList.remove('hidden');
        } else {
          card.classList.add('hidden');
        }
      });
    }

    function handleInquirySubmit(e) {
      e.preventDefault();
      const name = document.getElementById('inqName').value.trim();
      const phone = document.getElementById('inqPhone').value.trim();
      const pkg = document.getElementById('inqPackage').value;
      const text = encodeURIComponent(`السلام عليكم، أنا ${name} (الهاتف: ${phone})، أرغب في الاستفسار عن ${pkg}`);
      window.open(`https://wa.me/212662574740?text=${text}`, '_blank');
      alert('شكراً لك، تم توجيه طلبك مباشرة إلى واتساب الوكالة!');
    }

    // Toggle Mobile Navigation Drawer
    function toggleMobileMenu() {
      const menu = document.getElementById('mobileMenu');
      if (menu) {
        menu.classList.toggle('hidden');
      }
    }

    // Transparent Floating Navbar Scroll Behavior
    const navBarEl = document.getElementById('nav-bar');
    const topBarEl = document.getElementById('top-bar');
    window.addEventListener('scroll', () => {
      if (window.scrollY > 20) {
        if (navBarEl) {
          navBarEl.classList.remove('bg-black/25', 'border-white/10');
          navBarEl.classList.add('bg-primary-950/95', 'shadow-xl', 'border-gold-500/30');
        }
        if (topBarEl) {
          topBarEl.classList.remove('bg-primary-950/40', 'border-white/10');
          topBarEl.classList.add('bg-primary-950/90', 'border-gold-500/20');
        }
      } else {
        if (navBarEl) {
          navBarEl.classList.add('bg-black/25', 'border-white/10');
          navBarEl.classList.remove('bg-primary-950/95', 'shadow-xl', 'border-gold-500/30');
        }
        if (topBarEl) {
          topBarEl.classList.add('bg-primary-950/40', 'border-white/10');
          topBarEl.classList.remove('bg-primary-950/90', 'border-gold-500/20');
        }
      }
    }, { passive: true });

    // Ensure clean light theme by default
    document.documentElement.classList.remove('dark');
    try {
      localStorage.removeItem('rak_theme');
    } catch (e) {}

//
